const AjvConstructor = ajvPackage.default;
const ajvOptions = {
  coerceTypes: false,
  useDefaults: false,
  removeAdditional: false,
  strict: false,
  validateFormats: false,
  format: false as const,
};
const ajv = new AjvConstructor(ajvOptions);

function compileToolSchema(definition: ToolDefinition): ValidateFunction {
  try {
    return ajv.compile(definition.inputSchema);
  } catch (error) {
    const reason = error instanceof Error ? error.message : String(error);
    throw new Error(`Invalid inputSchema for tool "${definition.name}": ${reason}`, {cause: error});
  }
}

interface ValidationErrorLike {
  keyword: string;
  instancePath?: string;
  dataPath?: string;
  message?: string;
}

function formatValidationErrors(errors: readonly ValidationErrorLike[] | null | undefined): string {
  if (!errors || errors.length === 0) return 'input did not match schema';
  return errors.map(formatValidationError).join('; ');
}

function formatValidationError(error: ValidationErrorLike): string {
  const rawPath = error.instancePath ?? error.dataPath ?? '';
  const path = rawPath.startsWith('/') ? rawPath.slice(1).replace(/\//g, '.') : rawPath.replace(/^\./, '');
  const message = error.message ?? error.keyword;
  return path ? `${path} ${message}` : message;
}

